import { MeshBasicNodeMaterial, PlaneGeometry, Group, DirectionalLight } from 'three/webgpu';
import { uv, vec3, mix, smoothstep } from 'three/tsl';
import { gsap } from 'gsap';

export function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new Group();

  const colors = {
    background: '#0b0b10',
    surface: '#101017',
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    gradientStops: [
      { at: 0, hex: '#0b0b10' },
      { at: 1, hex: '#13131a' }
    ]
  };

  // --- STAGE BACKDROP ---
  const backdropGeo = new PlaneGeometry(7.0, 5.5);
  const backdropMat = new MeshBasicNodeMaterial({ depthWrite: false });

  // Custom vertical gradient via TSL node
  const vUv = uv();
  const topColor = vec3(0.12, 0.12, 0.16); // #13131a scaled down slightly
  const bottomColor = vec3(0.04, 0.04, 0.06); // #0b0b10
  const gradMix = mix(bottomColor, topColor, vUv.y);

  // Subtle mono grain pattern mimicking 1.5% micro-grain
  const grainSeed = vUv.x.mul(12345.0).sin().mul(vUv.y.mul(67890.0).sin());
  const grainVal = grainSeed.fract().sub(0.5).mul(0.015);
  backdropMat.colorNode = gradMix.add(grainVal);

  const backdropMesh = new THREE.Mesh(backdropGeo, backdropMat);
  backdropMesh.position.set(0, 0, -1.5);
  group.add(backdropMesh);

  // --- LOCAL LIGHTS ---
  // Ambient is standard; we append local key & rim lights as requested by W-PCP visual tone
  const keyLight = new DirectionalLight('#ffffff', 1.1);
  keyLight.position.set(2, 3, 4);
  group.add(keyLight);

  const rimLight = new DirectionalLight(colors.accent, 0.8);
  rimLight.position.set(-3, -2, -2);
  group.add(rimLight);

  // --- TEXT LAYERS ---
  const timelines = [];

  // 1. Caption Kicker: "NOVA ATELIER / CALIBRE PROGRAM"
  const captionText = ctx.fontAtlas.createText('NOVA ATELIER / CALIBRE PROGRAM', {
    fontSize: 22,
    color: colors.paper,
    align: 'center',
    letterSpacingPx: 3
  });
  captionText.position.set(0, 1.15, 0.1);
  group.add(captionText);

  // 2. Hero Headline: "TIME, MACHINED."
  // Split hero text into words/glyphs to construct staggered kinetic layer
  const words = 'TIME, MACHINED.'.split(' ');
  const heroGroup = new Group();
  heroGroup.position.set(0, 0.4, 0);
  group.add(heroGroup);

  const glyphHolders = [];
  let totalWidthAccum = 0;
  const wordSpacing = 0.28;

  words.forEach((word, wordIdx) => {
    // Generate different depth layer per word: 0.12 for first, 0.0 for second
    const wordZOffset = wordIdx === 0 ? 0.12 : 0.0;
    const wordGroup = new Group();
    wordGroup.position.z = wordZOffset;

    let localX = 0;
    for (let char of word) {
      const charObj = ctx.fontAtlas.createText(char, {
        fontSize: 74,
        color: colors.paper,
        align: 'left'
      });
      charObj.position.x = localX;
      wordGroup.add(charObj);
      glyphHolders.push(charObj);
      localX += 0.42; // Fixed metric increment for neat monospaced spacing
    }

    wordGroup.position.x = totalWidthAccum;
    totalWidthAccum += localX + wordSpacing;
    heroGroup.add(wordGroup);
  });

  // Re-center primary hero group horizontally based on width calculation
  heroGroup.position.x = -totalWidthAccum / 2.3;

  // 3. Accent Underline Rule
  const lineGeo = new PlaneGeometry(2.6, 0.045);
  const lineMat = new MeshBasicNodeMaterial({
    color: colors.accent,
    transparent: true,
    opacity: 0.9
  });
  const underlineMesh = new THREE.Mesh(lineGeo, lineMat);
  underlineMesh.position.set(0, -0.05, 0.05);
  underlineMesh.scale.x = 0;
  group.add(underlineMesh);

  // 4. Subhead: "Every calibre begins as a solid billet."
  const subheadText = ctx.fontAtlas.createText('Every calibre begins as a solid billet.', {
    fontSize: 40,
    color: colors.paper,
    align: 'center'
  });
  subheadText.position.set(0, -0.65, 0.15);
  subheadText.scale.setScalar(0.5);
  subheadText.children.forEach(c => {
    if (c.material) {
      c.material.transparent = true;
      c.material.opacity = 0;
    }
  });
  group.add(subheadText);

  // --- TRANSITION ANIMATIONS & GSAP ---
  const masterTimeline = gsap.timeline();
  timelines.push(masterTimeline);

  // Animate Hero Glyphs (kinetic-text logic)
  glyphHolders.forEach((glyph, i) => {
    const originalY = glyph.position.y;
    glyph.position.y = originalY - 0.35;

    // Set transparent ready state
    glyph.children.forEach(child => {
      if (child.material) {
        child.material.transparent = true;
        child.material.opacity = 0;
      }
    });

    masterTimeline.to(glyph.position, {
      y: originalY,
      duration: 0.7,
      ease: 'power3.out'
    }, i * 0.06);

    glyph.children.forEach(child => {
      if (child.material) {
        masterTimeline.to(child.material, {
          opacity: 1,
          duration: 0.7,
          ease: 'power3.out'
        }, i * 0.06);
      }
    });
  });

  const lastGlyphTime = glyphHolders.length * 0.06;

  // Final glyph triggers weighted-settle on overall hero container elements
  masterTimeline.fromTo(heroGroup.scale, 
    { x: 1.04, y: 1.04, z: 1.04 },
    { x: 1.00, y: 1.00, z: 1.00, duration: 0.9, ease: 'power4.out' },
    lastGlyphTime
  );

  // Underline scale horizontal rise transition
  masterTimeline.to(underlineMesh.scale, {
    x: 1,
    duration: 0.5,
    ease: 'power2.out'
  }, lastGlyphTime + 0.12);

  // Fade Up Subhead content
  subheadText.position.y -= 0.2;
  masterTimeline.to(subheadText.position, {
    y: -0.65,
    duration: 0.5,
    ease: 'power2.out'
  }, lastGlyphTime + 0.15);

  subheadText.children.forEach(child => {
    if (child.material) {
      masterTimeline.to(child.material, {
        opacity: 1,
        duration: 0.5,
        ease: 'power2.out'
      }, lastGlyphTime + 0.15);
    }
  });

  // Apply cinematic primitives via context hook
  const appliedPrimitive = ctx.primitives['kinetic-text'](heroGroup, {
    staggerMs: 60,
    riseUnits: 0.35
  });

  // --- CLEANUP ---
  group.userData = {
    cleanup() {
      timelines.forEach(tl => tl.kill());
      if (appliedPrimitive && typeof appliedPrimitive.cleanup === 'function') {
        appliedPrimitive.cleanup();
      }
      backdropGeo.dispose();
      backdropMat.dispose();
      lineGeo.dispose();
      lineMat.dispose();
    }
  };

  return group;
}
